/**
 * Loads the pad geometry JSON of a footprint (public/data/footprints/pads,
 * generated by scripts/generate-footprint-pads.mjs). Results are cached for
 * the session: the files are static.
 */
import type { FootprintPads } from '@/utils/kicad/footprint-pads'

const cache = new Map<string, Promise<FootprintPads>>()

/** URL of a footprint's pad JSON, by footprint name (e.g. `D_SOD-123F`). */
export function getFootprintPadsUrl(name: string): string {
  return `/data/footprints/pads/${name}.json`
}

/** Footprint name from a preview SVG filename (`D_SOD-123F.svg` → `D_SOD-123F`). */
export function footprintNameFromSvg(filename: string): string {
  return filename.replace(/\.svg$/, '')
}

export function loadFootprintPads(name: string): Promise<FootprintPads> {
  let pending = cache.get(name)
  if (!pending) {
    pending = fetch(getFootprintPadsUrl(name)).then(async (response) => {
      if (!response.ok) {
        throw new Error(`Failed to load pads of ${name}: ${response.status} ${response.statusText}`)
      }
      return (await response.json()) as FootprintPads
    })
    // a failed load may succeed later (e.g. offline), so don't keep it
    pending.catch(() => cache.delete(name))
    cache.set(name, pending)
  }
  return pending
}
